SELECT '1. A 類 18 支：anon、authenticated 不可執行；service_role 可執行；授權清單無 PUBLIC' AS item, (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account') AND NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE') AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND p.proacl IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0)) = 18 AS ok
UNION ALL SELECT '2. _hotelnabe_enqueue_days：anon 不可、authenticated／service_role 可、授權清單無 PUBLIC', (SELECT NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND has_function_privilege('authenticated', p.oid, 'EXECUTE') AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND p.proacl IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = '_hotelnabe_enqueue_days')
UNION ALL SELECT '3. B 類 ensure_trip_share_slug 維持現狀：anon、authenticated 可執行', (SELECT has_function_privilege('anon', p.oid, 'EXECUTE') AND has_function_privilege('authenticated', p.oid, 'EXECUTE') FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'ensure_trip_share_slug')
UNION ALL SELECT '4. C 類 8 支維持現狀：anon 不可、authenticated 可執行', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('delete_package_season', 'delete_pricing_template_group', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type') AND NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND has_function_privilege('authenticated', p.oid, 'EXECUTE')) = 8
UNION ALL SELECT '5. 呼叫 A 類函式的 SECURITY DEFINER 函式（觸發器等），其擁有者仍可執行目標', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_proc t ON t.pronamespace = 'public'::regnamespace AND t.oid <> p.oid AND t.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account') WHERE p.pronamespace = 'public'::regnamespace AND p.prosecdef AND p.prosrc ~ ('\m' || t.proname || '\M') AND NOT has_function_privilege(p.proowner, t.oid, 'EXECUTE'))
UNION ALL SELECT '6. 28 支函式內容指紋與 precheck 相同（本行最後的常數請換成 precheck 第 3 段 FP_ALL 的值）', (SELECT md5(string_agg(p.oid::regprocedure::text || '=' || md5(replace(p.prosrc, E'\r', '')), ',' ORDER BY p.oid::regprocedure::text)) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'delete_package_season', 'delete_pricing_template_group', 'ensure_trip_share_slug', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type')) = '__PASTE_PRECHECK_FP_ALL__'
UNION ALL SELECT '7. 28 支仍全部是 SECURITY DEFINER', NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'delete_package_season', 'delete_pricing_template_group', 'ensure_trip_share_slug', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type') AND NOT p.prosecdef);

SELECT p.oid::regprocedure::text AS func, COALESCE(p.proacl::text, 'NULL') AS proacl_after, has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_exec, has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_exec, md5(replace(p.prosrc, E'\r', '')) AS fp
FROM pg_proc p
WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'delete_package_season', 'delete_pricing_template_group', 'ensure_trip_share_slug', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type')
ORDER BY 1;
